def add_elements(arr, k):
    # Validate input
    if k < 1:
        raise ValueError("k must be at least 1")

    # Filter elements with at most two digits from the first k elements of arr
    filtered_elements = [x for x in arr[:k] if abs(x) <= 99]

    # Calculate the sum of filtered elements
    return sum(filtered_elements)
